const viewKey=()=>state.trip?tab+'|'+(tab==='plan'?curDay:tab==='more'?morePage:tab==='places'?placeFilter:''):'empty';
function rememberScroll(){scrollPositions.set(viewKey(),window.scrollY);}
function restoreScroll(){window.scrollTo({top:scrollPositions.get(viewKey())||0,behavior:'instant'});}
