function inlineMoney(n){return `약 ${fmt(krw(n))}원 <small>NT$${fmt(n,2)}</small>`;}
function currentFareReference(value){const known=n=>Number.isFinite(n)&&n>=0;let amount=null;if(known(value))amount=fmt(krw(value));else if(value&&known(value.min)&&known(value.max)&&value.max>=value.min)amount=fmt(krw(value.min))+'–'+fmt(krw(value.max));return amount===null?'':'현재 적용 환율 참고 · 약 '+amount+'원';}
function routeFareText(value,text){const reference=currentFareReference(value);return text+(reference?' · '+reference:'');}
