function quoteStamp(ts){return new Intl.DateTimeFormat('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'}).format(ts);}
function untilText(ms){const n=Math.max(0,Math.ceil(ms/C.MIN));if(n>=1440)return Math.floor(n/1440)+'일 '+Math.floor(n%1440/60)+'시간 전';if(n>=60)return Math.floor(n/60)+'시간 '+n%60+'분 전';return n+'분 전';}
