let receiptUIInstance=null;
function receiptStatus(status){const button=$('#receiptQueueStatus');if(!button)return;const intake=status.intake&&!status.intake.done,active=status.queued+status.analyzing;button.hidden=!intake&&!status.remaining&&!status.error;button.textContent=intake?'영수증 사진 접수 중 · '+status.intake.processed+'/'+status.intake.total:active?'영수증 분석 중 · '+active+'장 남음':status.remaining?'영수증 검토 · '+status.remaining+'장':status.error?'영수증 저장 상태 확인':'';}
const receiptManager={
 ensure(){if(!window.ReceiptUI||!window.ReceiptQueue||!window.ReceiptCore){toast('영수증 기능을 불러오지 못했습니다. 앱 업데이트를 확인해 주세요.');return null;}if(!receiptUIInstance)receiptUIInstance=ReceiptUI.create({showSheet,getContainer:()=>$('#sheetContent'),getExpenses:()=>C.clone(state.expenses),getSettings:()=>({...state.settings,rate:appliedRate(),rateSnapshot:appliedRate()}),getAppliedRate:()=>appliedRate(),markSheetClean:()=>{if($('#sheet').open&&$('#sheetContent .receipt-app')&&!sheetDirty)markSheetClean();},addExpense:addReceiptExpense,toast,onStatus:receiptStatus,storageKey:KEY});return receiptUIInstance;},
 open(){return this.ensure()?.open();},openQueue(){return this.ensure()?.openQueue();},
 resume(){try{return this.ensure()?.resumeQueue().catch(e=>console.warn('Receipt resume:',e.message));}catch(e){console.warn('Receipt setup:',e.message);}}
};
function addReceiptExpense(entry){
 const raw=localStorage.getItem(KEY),latest=raw?validateBackup(JSON.parse(raw)):state;
 const old=latest.expenses.find(x=>x.id===entry.id||(entry.receiptId&&x.receiptId===entry.receiptId));if(old){state=latest;render(false);return C.clone(old);}
 const normalized=C.normalizeExpense(entry),next=validateBackup({...C.clone(latest),expenses:[...C.clone(latest.expenses),normalized]});
 next.logs.unshift({time:Date.now(),message:'영수증 확인 후 지출 등록'});next.logs=next.logs.slice(0,80);
 // Commit durable storage first. A failed write must never look like a saved expense.
 try{localStorage.setItem(KEY,JSON.stringify(next));}catch(e){throw Error('지출 저장 공간이 부족하거나 저장이 차단되었습니다. 사진은 보관 상태를 확인하고 다시 시도해 주세요.');}
 snapshot(latest);state=next;storageOK=true;render(false);return C.clone(normalized);
}

