function patchActive(session){return routePatchSession===session&&$('#sheet').open&&!$('#sheet').classList.contains('closing')&&!!$('#routePatchPreview');}
function patchErrorText(error){if(!error.code)return error.message||'이동안을 처리하지 못했습니다.';if(error.code==='oversize')return '이동안 파일이 너무 크거나 복잡합니다. 256 KB 이하의 원본 이동안 파일을 다시 선택해 주세요.';if(error.code==='crypto-unavailable')return '이 환경에서 이동안 일치 여부를 검사할 수 없습니다. 설치한 앱이나 HTTPS 주소에서 다시 열어 주세요.';if(['stale-selection','invalid-selection','unavailable-selection'].includes(error.code))return '선택한 이동안이 현재 일정 또는 출발시각과 맞지 않습니다. 파일을 다시 열어 비교해 주세요.';if(error.code==='missing-trip')return '이 기기에 여행 일정이 없습니다. 개인 여행 파일을 먼저 불러와 주세요.';return '이동안 파일의 형식이나 조회 정보가 올바르지 않습니다. 원본 파일을 다시 확인해 주세요.';}
function patchReason(reason){return ({'baseline-mismatch':'기기에 저장된 경로·출발시각·장소 정보가 조회 기준과 달라 건너뜁니다.','missing-item':'이 기기에 같은 일정 ID가 없어 건너뜁니다.','not-movement':'이동 일정 ID가 아니므로 적용하지 않습니다.','leg-not-pending':'이미 진행하거나 완료한 일정에는 적용하지 않습니다.','leg-protected':'항공·고정·확정 예약 일정은 보호합니다.','already-applied':'같은 이동안을 이미 적용했습니다.','applied-leg-changed':'이동안 적용 후 일정이 바뀌어 다시 적용하지 않습니다.','applied-patch-content-changed':'같은 이동안 ID의 내용이 달라 다시 확인해야 합니다.','no-applicable-options':'현재 출발시각에 적용할 수 있는 조회 결과가 없습니다.','planned-departure-mismatch':'조회한 출발시각과 현재 일정이 달라 적용할 수 없습니다.','source-unavailable':'조회에서 이용 가능한 경로를 확인하지 못했습니다.'})[reason]||'현재 일정과 안전하게 연결할 수 없어 적용하지 않습니다.';}
